def distance(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    if dx < 0:
        dx = -dx
    if dy < 0:
        dy = -dy
    return dx + dy

plan = scan()
margins = []
for target in plan["targets"]:
    nearest = distance(plan["rivals"][0], target)
    for rival in plan["rivals"]:
        rival_distance = distance(rival, target)
        if rival_distance < nearest:
            nearest = rival_distance
    margin = nearest - distance(plan["player"], target)
    margins.append(margin)
    submit(margin)
if margins[1] > margins[0]:
    move("left")
    move("left")
